public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() < k) {
        return false;
    }

    int total = 1 << k; // 2^k
    boolean[] seen = new boolean[total];
    int count = 0;

    int val = 0;
    for (int i = 0; i < s.length(); i++) {
        val = (val * 2 + (s.charAt(i) - '0')) % total;

        if (i >= k - 1) {
            if (i > k - 1) {
                val = val - ((s.charAt(i - k) - '0') << (k - 1));
            }

            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }

    return false;
}

