public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n;

    int i = n - 1;
    while (k > 0) {
        int add = Math.min(25, k);
        result.setCharAt(i, (char) ('a' + add));
        k -= add;
        i--;
    }
    return result.toString();
}

