public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Create a DP array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];
    // Initialize the DP array with a maximum value
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    // Base case: 0 can be represented by 0 perfect squares
    dp[0] = 0;

    // Precompute the perfect squares less than or equal to n
    int maxSquareIndex = (int) Math.sqrt(n);
    int[] squares = new int[maxSquareIndex + 1];
    for (int i = 1; i <= maxSquareIndex; i++) {
        squares[i] = i * i;
    }

    // Fill the DP array
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= maxSquareIndex; j++) {
            if (i >= squares[j]) {
                dp[i] = Math.min(dp[i], dp[i - squares[j]] + 1);
            }
        }
    }

    return dp[n];
}

